    "path": "src/main/webapp/WEB-INF/web.xml",
    "content": "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<web-app xmlns=\"http://xmlns.jcp.org/xml/ns/javaee\"\n         xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"\n         xsi:schemaLocation=\"http://xmlns.jcp.org/xml/ns/javaee \n         http://xmlns.jcp.org/xml/ns/javaee/web-app_4_0.xsd\"\n         version=\"4.0\">\n\n    <display-name>MediCare+ Hospital Management System</display-name>\n    <description>\n        Java Web-Based Hospital Portal matching Galgotias University Rubric 2.\n    </description>\n\n    <!-- Session Management (Review 1: Servlets & Web Integration) -->\n    <session-config>\n        <session-timeout>30</session-timeout> <!-- 30 Minutes Session Inactivity Timeout -->\n        <cookie-config>\n            <http-only>true</http-only>\n            <secure>false</secure> <!-- Set true in production HTTPS -->\n        </cookie-config>\n        <tracking-mode>COOKIE</tracking-mode>\n    </session-config>\n\n    <!-- 1. Authentication Filter -->\n    <filter>\n        <filter-name>AuthenticationFilter</filter-name>\n        <filter-class>com.medicare.servlet.AuthenticationFilter</filter-class>\n    </filter>\n    <filter-mapping>\n        <filter-name>AuthenticationFilter</filter-name>\n        <url-pattern>/api/appointments/*</url-pattern>\n        <url-pattern>/api/records/*</url-pattern>\n        <url-pattern>/api/slip/*</url-pattern>\n    </filter-mapping>\n\n    <!-- 2. Auth Servlet (Login / Register / Logout / Session Check) -->\n    <servlet>\n        <servlet-name>AuthServlet</servlet-name>\n        <servlet-class>com.medicare.servlet.AuthServlet</servlet-class>\n    </servlet>\n    <servlet-mapping>\n        <servlet-name>AuthServlet</servlet-name>\n        <url-pattern>/api/auth/*</url-pattern>\n    </servlet-mapping>\n\n    <!-- 3. Appointment Servlet (Booking / Listing / Cancellation with JDBC Transactions) -->\n    <servlet>\n        <servlet-name>AppointmentServlet</servlet-name>\n        <servlet-class>com.medicare.servlet.AppointmentServlet</servlet-class>\n    </servlet>\n    <servlet-mapping>\n        <servlet-name>AppointmentServlet</servlet-name>\n        <url-pattern>/api/appointments/*</url-pattern>\n    </servlet-mapping>\n\n    <!-- 4. Medical Consultation Slip Servlet (PDF Stream / HTML Receipt) -->\n    <servlet>\n        <servlet-name>MedicalSlipServlet</servlet-name>\n        <servlet-class>com.medicare.servlet.MedicalSlipServlet</servlet-class>\n    </servlet>\n    <servlet-mapping>\n        <servlet-name>MedicalSlipServlet</servlet-name>\n        <url-pattern>/api/slip/*</url-pattern>\n    </servlet-mapping>\n\n    <!-- 5. Medical Records Vault Servlet (EHR CRUD) -->\n    <servlet>\n        <servlet-name>MedicalRecordServlet</servlet-name>\n        <servlet-class>com.medicare.servlet.MedicalRecordServlet</servlet-class>\n    </servlet>\n    <servlet-mapping>\n        <servlet-name>MedicalRecordServlet</servlet-name>\n        <url-pattern>/api/records/*</url-pattern>\n    </servlet-mapping>\n\n    <welcome-file-list>\n        <welcome-file>index.html</welcome-file>\n        <welcome-file>index.jsp</welcome-file>\n    </welcome-file-list>\n\n</web-app>\n"
